'use client';
import { useState } from 'react';

export default function Tabs() {
  const [active, setActive] = useState(0);
  const tabs = ['{{tab_one}}', '{{tab_two}}'];
  const content = ['{{content_one}}', '{{content_two}}'];
  return (
    <div>
      <div className="flex border-b">
        {tabs.map((t, i) => (
          <button key={t} onClick={() => setActive(i)} className={`px-4 py-2 ${active === i ? 'border-b-2 border-indigo-600' : ''}`}>{t}</button>
        ))}
      </div>
      <div className="p-4">{content[active]}</div>
    </div>
  );
}
